{
  "packet_id": "H6-T02-3",
  "claim_id": "C060",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C060.component",
    "value": "Failure to detect a change does not exclude contention.",
    "scope": "Limit on interpreting a null experimental response.",
    "provenance": {
      "refs": [
        {
          "source_id": "P039",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly states that nondetection does not exclude contention."
    }
  },
  "signal_basis": {
    "component_id": "C060.signal_basis",
    "value": "A controlled reduction in concurrency produces no detectable change in the measured response relative to baseline and any unchanged comparison pool.",
    "scope": "The tested cohort, concurrency range, worker versions, and operating conditions.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
